208	    /**
209	     * The owner's member id with any de-duplication suffix stripped — the base
210	     * {@code '<REGION><FY><HASH8><CHK>'} value from which the region and fiscal-year segments are read.
211	     * The base carries no {@code '-'}; the collision suffix (when present) is {@code '-<n>'}, so the
212	     * base is the portion before the first {@code '-'}.
213	     */
214	    private String memberIdBase() {
215	        int dash = this.memberId.indexOf('-');
216	        return dash < 0 ? this.memberId : this.memberId.substring(0, dash);
217	    }
