296	    /**
297	     * The owner's initials: the upper-cased first letters of the first and last name,
298	     * dot-separated with a trailing dot (e.g. {@code 'J.S.'}).
299	     */
300	    @Transient
301	    public String getInitials() {
302	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
303	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
304	    }
