306	    /**
307	     * The fiscal year a date falls in. The fiscal year starts on 1 July and is identified by the
308	     * calendar year in which it ends: a date in July through December belongs to the fiscal year
309	     * ending the following calendar year, a date in January through June to the fiscal year ending
310	     * that same calendar year.
311	     */
312	    private static int fiscalYearOf(LocalDate date) {
313	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
314	    }
315	
316	    /**
317	     * The owner's fiscal year, formatted {@code 'FY<YY>'} where {@code YY} is the two-digit fiscal-year
318	     * segment carried by the owner's {@link #getMemberId() member id} (e.g. {@code 'FY26'} for a member
319	     * id whose {@code <FY>} segment is {@code '26'}). The member id bakes in the fiscal year (which
320	     * starts on 1 July) of the business-day-adjusted registration date at creation time, so this reads
321	     * that value back from the member id. {@code null} until the owner has a member id.
322	     */
323	    @Transient
324	    public String getFiscalYear() {
325	        if (this.memberId == null) {
326	            return null;
327	        }
328	        String base = memberIdBase();
329	        if (base.length() < 11) {
330	            return null;
331	        }
332	        return "FY" + base.substring(base.length() - 11, base.length() - 9);
333	    }
334	
335	    /**
336	     * The owner's membership points, a score accumulated from the owner's own fields. It starts at
337	     * 0 and gains: 2 when the owner has an email address; 1 when the owner is unique
338	     * ({@code namesakeCount} is 0); 2 when the owner belongs to a household of 3 or more members
339	     * (the owner together with their pets); and 3 when the owner's tenure spans at least one elapsed
340	     * fiscal year, measured as the difference between the fiscal year of today and the fiscal year of
341	     * {@code registrationDate}. Because a newly created owner has zero elapsed fiscal years of tenure,
342	     * a new owner never earns the tenure points. The score feeds {@link #getMembershipLevel()}.
343	     */
344	    @Transient
345	    public Integer getMembershipPoints() {
346	        int points = 0;
347	        boolean hasEmail = this.email != null && !this.email.isBlank();
348	        if (hasEmail) {
349	            points += 2;
350	        }
351	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
352	        if (unique) {
353	            points += 1;
354	        }
355	        int householdSize = 1 + getPetsInternal().size();
356	        if (householdSize >= 3) {
357	            points += 2;
358	        }
359	        boolean tenured = this.registrationDate != null
360	            && fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate) > 0;
361	        if (tenured) {
362	            points += 3;
363	        }
364	        return points;
365	    }
366	
367	    /**
368	     * The owner's numeric membership level, from 1 to 4. By default it is derived from
369	     * {@link #getMembershipPoints()}: level 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and
370	     * 4 for 6 or more points. When a level has been assigned and stored at creation time (the capped
371	     * level computed against the owner's household), that stored value is returned instead, so the
372	     * level read back for the owner reflects the household ceiling applied when the owner was created.
373	     */
374	    @Transient
375	    public Integer getMembershipLevel() {
376	        if (this.membershipLevel != null) {
377	            return this.membershipLevel;
378	        }
379	        return getDerivedMembershipLevel();
380	    }
