382	    /**
383	     * Stores the owner's membership level, overriding the value otherwise derived from the owner's
384	     * membership points. Used at creation time to persist the household-capped level.
385	     */
386	    public void setMembershipLevel(Integer membershipLevel) {
387	        this.membershipLevel = membershipLevel;
388	    }
