390	    /**
391	     * The owner's membership level derived purely from {@link #getMembershipPoints()}, before any
392	     * household cap: level 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more
393	     * points.
394	     */
395	    @Transient
396	    public Integer getDerivedMembershipLevel() {
397	        int points = getMembershipPoints();
398	        if (points >= 6) {
399	            return 4;
400	        }
401	        if (points >= 4) {
402	            return 3;
403	        }
404	        if (points >= 2) {
405	            return 2;
406	        }
407	        return 1;
408	    }
