410	    /**
411	     * The owner's locality: the canonical region carried by the {@link #getMemberId() member id}, which
412	     * is its leading {@code <REGION>} segment — everything preceding the two-digit fiscal year, the
413	     * eight-character {@code HASH8} and the single check digit that complete the base member id (e.g.
414	     * {@code 'NSW'} for member id {@code 'NSW261A2B3C4D7'}). The region is the one derived from the
415	     * postcode at creation time and baked into the identity. {@code 'UNKNOWN'} when the owner has no
416	     * member id yet.
417	     */
418	    @Transient
419	    public String getLocality() {
420	        if (this.memberId == null) {
421	            return "UNKNOWN";
422	        }
423	        String base = memberIdBase();
424	        if (base.length() < 12) {
425	            return "UNKNOWN";
426	        }
427	        return base.substring(0, base.length() - 11);
428	    }
