430	    /**
431	     * Fixed region-to-timezone lookup mapping each canonical region to its IANA timezone name:
432	     * {@code NSW -> 'Australia/Sydney'}, {@code VIC -> 'Australia/Melbourne'},
433	     * {@code QLD -> 'Australia/Brisbane'}.
434	     */
435	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
436	        "NSW", "Australia/Sydney",
437	        "VIC", "Australia/Melbourne",
438	        "QLD", "Australia/Brisbane");
439	
440	    /**
441	     * The owner's timezone: the IANA name derived from the owner's {@link #getLocality() locality}
442	     * via the fixed region-to-timezone table ({@code NSW -> 'Australia/Sydney'},
443	     * {@code VIC -> 'Australia/Melbourne'}, {@code QLD -> 'Australia/Brisbane'}). {@code null} when
444	     * the locality is not one of these regions.
445	     */
446	    @Transient
447	    public String getTimezone() {
448	        return REGION_TIMEZONE.get(getLocality());
449	    }
450	
451	    /**
452	     * The owner's segment, formatted {@code '<TIER>_<AREA>'}, one of {@code 'PREMIUM_METRO'},
453	     * {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or {@code 'STANDARD_REGIONAL'}. The
454	     * {@code <TIER>} is {@code 'PREMIUM'} when the owner's {@link #getMembershipLevel() membership
455	     * level} is 3 or more, otherwise {@code 'STANDARD'}. The {@code <AREA>} is {@code 'METRO'} when
456	     * the owner's {@link #getLocality() locality} is a known region (NSW, VIC or QLD), otherwise
457	     * {@code 'REGIONAL'}. Derived from the owner's own fields.
458	     */
459	    @Transient
460	    public String getOwnerSegment() {
461	        Integer level = getMembershipLevel();
462	        String tier = level != null && level >= 3 ? "PREMIUM" : "STANDARD";
463	        String area = REGION_TIMEZONE.containsKey(getLocality()) ? "METRO" : "REGIONAL";
464	        return tier + "_" + area;
465	    }
