467	    /**
468	     * The owner's identity key: a single derived value that consolidates all duplicate detection,
469	     * the lower-case hex SHA-256 digest of {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'}.
470	     * The telephone is the stored E.164 value, the email its stored lower-cased form (empty when the
471	     * owner has none), and the final segment the American Soundex code of the owner's last name. Two
472	     * owners are duplicates only when their whole identity keys are equal; because the telephone is
473	     * part of the key, two owners with the same last name and postcode but different telephones have
474	     * different identity keys and are not hard duplicates.
475	     */
476	    @Transient
477	    public String getIdentityKey() {
478	        String telephonePart = this.telephone == null ? "" : this.telephone;
479	        String emailPart = this.email == null ? "" : this.email;
480	        String soundexPart = soundex(this.getLastName());
481	        return HashUtils.sha256Hex(telephonePart + "|" + emailPart + "|" + soundexPart);
482	    }
483	
484	    /**
485	     * The American Soundex code of the owner's last name, used to group similar-sounding surnames for
486	     * soft (possible-duplicate) matching. Derived from the owner's own last name.
487	     */
488	    @Transient
489	    public String getLastNameSoundex() {
490	        return soundex(this.getLastName());
491	    }
492	
493	    /**
494	     * Computes the American Soundex code of a name: its first letter (upper-cased) followed by three
495	     * digits derived from the remaining consonants, with adjacent duplicate codes (and codes separated
496	     * only by {@code H} or {@code W}) collapsed, then zero-padded and truncated to four characters. A
497	     * {@code null} or letter-free value yields an empty string.
498	     *
499	     * @param value the name to encode
500	     * @return the four-character Soundex code, or an empty string
501	     */
502	    private static String soundex(String value) {
503	        if (value == null) {
504	            return "";
505	        }
506	        String letters = value.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
507	        if (letters.isEmpty()) {
508	            return "";
509	        }
510	        StringBuilder code = new StringBuilder();
511	        code.append(letters.charAt(0));
512	        char previousDigit = soundexDigit(letters.charAt(0));
513	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
514	            char c = letters.charAt(i);
515	            char digit = soundexDigit(c);
516	            if (digit != '0' && digit != previousDigit) {
517	                code.append(digit);
518	            }
519	            if (c != 'H' && c != 'W') {
520	                previousDigit = digit;
521	            }
522	        }
523	        while (code.length() < 4) {
524	            code.append('0');
525	        }
526	        return code.toString();
527	    }
528	
529	    /**
530	     * Maps a single upper-case letter to its Soundex digit, or {@code '0'} for the vowels and the
531	     * letters {@code H}, {@code W} and {@code Y} that carry no Soundex digit.
532	     */
533	    private static char soundexDigit(char c) {
534	        switch (c) {
535	            case 'B': case 'F': case 'P': case 'V':
536	                return '1';
537	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
538	                return '2';
539	            case 'D': case 'T':
540	                return '3';
541	            case 'L':
542	                return '4';
543	            case 'M': case 'N':
544	                return '5';
545	            case 'R':
546	                return '6';
547	            default:
548	                return '0';
549	        }
550	    }
