552	    /**
553	     * The owner's preferred contact channel, derived from the owner's own fields:
554	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
555	     */
556	    @Transient
557	    public String getContactPreference() {
558	        boolean hasEmail = this.email != null && !this.email.isBlank();
559	        return hasEmail ? "EMAIL" : "PHONE";
560	    }
