562	    /**
563	     * The owner's age band, derived from the owner's own fields: the whole number of years from
564	     * {@code birthDate} to {@code registrationDate} placed into a band — {@code 'MINOR'} when under
565	     * 18, {@code 'ADULT'} when 18 to 64, and {@code 'SENIOR'} when 65 or older. The age is measured
566	     * as of the registration date rather than today, so the band is stable over time. {@code null}
567	     * when the owner has no birth date (or no registration date to measure against).
568	     */
569	    @Transient
570	    public String getAgeBand() {
571	        if (this.birthDate == null || this.registrationDate == null) {
572	            return null;
573	        }
574	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
575	        if (age < 18) {
576	            return "MINOR";
577	        }
578	        if (age < 65) {
579	            return "ADULT";
580	        }
581	        return "SENIOR";
582	    }
