620	    /**
621	     * Return the Pet with the given name, or null if none found for this Owner.
622	     *
623	     * @param name to test
624	     * @return true if pet name is already in use
625	     */
626	    public Pet getPet(String name, boolean ignoreNew) {
627	        name = name.toLowerCase();
628	        for (Pet pet : getPetsInternal()) {
